use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts,
  pub api_diagnostic_facts: Isolette_Thermostat_Rust::RegulatorDiagnosticFacts
}

/// container for component's incoming port values and GUMBO state variables
pub struct PreStateContainer_wGSV {
  pub In_regulator_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  pub api_interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts,
  pub api_diagnostic_facts: Isolette_Thermostat_Rust::RegulatorDiagnosticFacts
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_interface_facts(container.api_interface_facts);
  put_diagnostic_facts(container.api_diagnostic_facts);
}

/// setter for component's incoming port values and GUMBO state variables
pub fn put_concrete_inputs_container_wGSV(container: PreStateContainer_wGSV)
{
  put_regulator_mode_state(container.In_regulator_mode_state);
  put_interface_facts(container.api_interface_facts);
  put_diagnostic_facts(container.api_diagnostic_facts);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts,
  diagnostic_facts: Isolette_Thermostat_Rust::RegulatorDiagnosticFacts)
{
  put_interface_facts(interface_facts);
  put_diagnostic_facts(diagnostic_facts);
}

/// setter for component's incoming port values and GUMBO state variables
pub fn put_concrete_inputs_wGSV(
  In_regulator_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts,
  diagnostic_facts: Isolette_Thermostat_Rust::RegulatorDiagnosticFacts)
{
  put_regulator_mode_state(In_regulator_mode_state);
  put_interface_facts(interface_facts);
  put_diagnostic_facts(diagnostic_facts);
}

/// setter for IN DataPort
pub fn put_interface_facts(value: Isolette_Thermostat_Rust::RegulatorInterfaceFacts)
{
  *extern_api::IN_interface_facts.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_diagnostic_facts(value: Isolette_Thermostat_Rust::RegulatorDiagnosticFacts)
{
  *extern_api::IN_diagnostic_facts.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_mode_for_interface() -> Isolette_Thermostat_Rust::ThermostatMode
{
  return extern_api::OUT_mode_for_interface.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for OUT DataPort
pub fn get_mode_for_heat() -> Isolette_Thermostat_Rust::ThermostatMode
{
  return extern_api::OUT_mode_for_heat.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for GUMBO State Variable
pub fn get_regulator_mode_state() -> Isolette_Thermostat_Rust::ThermostatMode
{
  unsafe {
    match &crate::app {
      Some(inner) => inner.regulator_mode_state,
      None => panic!("The app is None")
    }
  }
}

/// setter for GUMBO State Variable
pub fn put_regulator_mode_state(value: Isolette_Thermostat_Rust::ThermostatMode)
{
  unsafe {
    match &mut crate::app {
      Some(inner) => inner.regulator_mode_state = value,
      None => panic!("The app is None")
    }
  }
}
